/** 
 * Returns the max Android API version number available in directory 'dir'
 * @param dir
 * @return
 */
private int getMaxAPIAvailable(String dir){
  File d=new File(dir);
  if (!d.exists())   throw new RuntimeException("The Android platform directory you have" + "specified (" + dir + ") does not exist. Please check.");
  File[] files;
  try {
    files=d.listFiles();
    if (files == null) return -1;
  } catch (SecurityException e) {
    return -1;
  }
  int maxApi=-1;
  for (  File f : files) {
    String name=f.getName();
    if (f.isDirectory() && name.startsWith("android-")) {
      try {
        int v=Integer.decode(name.split("android-")[1]);
        if (v > maxApi)       maxApi=v;
      } catch (NumberFormatException e) {
        continue;
      }
    }
  }
  return maxApi;
}
